const langStorageKey = 'pe-lang';
const langSourceStorageKey = 'pe-lang-source';
const timezoneStorageKey = 'pe-community-timezone';

type I18nContextValue = {
  lang: Lang;
  setLang: (lang: Lang) => void;
  t: Dict;
  timezone: string;
  applyCommunityDefaults: (defaults?: CommunityDefaults | null) => void;
  refreshCommunityDefaults: () => Promise<CommunityDefaults | null>;
};

const I18nContext = createContext<I18nContextValue | null>(null);

export function LanguageProvider({ children }: { children: React.ReactNode }) {
  const [lang, setLangState] = useState<Lang>('en');
  const [timezone, setTimezone] = useState('UTC');
  const [languageReady, setLanguageReady] = useState(false);

  const applyCommunityDefaults = useCallback((defaults?: CommunityDefaults | null) => {
    const nextTimezone = timezoneValue(defaults?.timezone);
    if (nextTimezone) {
      setTimezone(nextTimezone);
      window.localStorage.setItem(timezoneStorageKey, nextTimezone);
    }
    const nextLang = languageValue(defaults?.defaultLanguage);
    const effectiveLanguage = resolveEffectiveLanguage(
      window.localStorage.getItem(langStorageKey),
      window.localStorage.getItem(langSourceStorageKey),
      nextLang,
    );
    setLangState(effectiveLanguage);
    document.documentElement.lang = effectiveLanguage;
  }, []);

  const refreshCommunityDefaults = useCallback(async () => {
    const user = await fetch(apiUrl('/auth/me'), {
      credentials: 'include',
      cache: 'no-store',
    }).then((response) => response.ok ? response.json() : null);
    const defaults = user?.community as CommunityDefaults | undefined;
    if (defaults) applyCommunityDefaults(defaults);
    return defaults ?? null;
  }, [applyCommunityDefaults]);

  useEffect(() => {
    const saved = languageValue(window.localStorage.getItem(langStorageKey));
    const source = window.localStorage.getItem(langSourceStorageKey);
    const savedTimezone = timezoneValue(window.localStorage.getItem(timezoneStorageKey));
    const explicitLanguage = source === 'user' ? saved : null;
    if (savedTimezone) setTimezone(savedTimezone);
    if (explicitLanguage) {
      setLangState(explicitLanguage);
      document.documentElement.lang = explicitLanguage;
      setLanguageReady(true);
    } else if (source === 'community') {
      window.localStorage.removeItem(langStorageKey);
      window.localStorage.removeItem(langSourceStorageKey);
    }

    let cancelled = false;
    async function initializeLanguage() {
      try {
        const defaults = await refreshCommunityDefaults().catch(() => null);
        if (cancelled) return;
        if (!defaults) {
          const bootstrap = await loadPublicInstanceBootstrap();
          if (!cancelled) applyCommunityDefaults(bootstrap);
        }
      } finally {
        if (!cancelled) setLanguageReady(true);
      }
    }
    void initializeLanguage();
    return () => {
      cancelled = true;
    };
  }, [applyCommunityDefaults, refreshCommunityDefaults]);

  const setLang = (next: Lang) => {
    setLangState(next);
    window.localStorage.setItem(langStorageKey, next);
    window.localStorage.setItem(langSourceStorageKey, 'user');
    document.documentElement.lang = next;
  };

  const value = useMemo(
    () => ({ lang, setLang, t: dictionaries[lang], timezone, applyCommunityDefaults, refreshCommunityDefaults }),
    [lang, timezone, applyCommunityDefaults, refreshCommunityDefaults],
  );
  return (
    <I18nContext.Provider value={value}>
      {languageReady ? children : <div className="min-h-dvh bg-[#020604]" aria-busy="true" />}
    </I18nContext.Provider>
  );
}

export function useI18n() {
  const context = useContext(I18nContext);
  if (!context) throw new Error('useI18n must be used within LanguageProvider');
  return context;
}

function languageValue(value: unknown): Lang | null {
  return value === 'fr' || value === 'en' ? value : null;
}

export function resolveEffectiveLanguage(
  storedLanguage: unknown,
  storedSource: unknown,
  communityLanguage: unknown,
): Lang {
  const explicitLanguage = storedSource === 'user' ? languageValue(storedLanguage) : null;
  return explicitLanguage ?? languageValue(communityLanguage) ?? 'en';
}

function timezoneValue(value: unknown) {
  if (typeof value !== 'string' || !value.trim()) return null;
  try {
    new Intl.DateTimeFormat(undefined, { timeZone: value.trim() });
    return value.trim();
  } catch {
    return null;
  }
}

export function LanguageSwitcher({ value, onChange }: { value?: Lang; onChange?: (lang: Lang) => void } = {}) {
  const { lang, setLang, t } = useI18n();
  const selectedLang = value ?? lang;
  const changeLanguage = onChange ?? setLang;
  return (
    <div className="flex rounded-full border border-white/10 bg-white/5 p-1" aria-label={t.common.language}>
      {(['en', 'fr'] as const).map((item) => (
        <button
          key={item}
          onClick={() => changeLanguage(item)}
          className={`rounded-full px-3 py-1 text-xs font-bold uppercase ${selectedLang === item ? 'bg-accent text-background' : 'text-white/70'}`}
          aria-pressed={selectedLang === item}
        >
          {item}
        </button>
      ))}
    </div>
  );
}

export function statusLabel(t: Dict, value?: string | null) {
  if (!value) return '';
  return t.status[value as keyof typeof t.status] ?? value;
}

export function auditLabel(t: Dict, value?: string | null) {
  if (!value) return t.audit.fallback;
  return t.audit[value as keyof typeof t.audit] ?? value;
}
